def score(program: str) -> float:
    try:
        import ast
        f = sum(isinstance(n, ast.FunctionDef) for n in ast.walk(ast.parse(program)))
        return min(1, (f + 1) / 5)
    except:
        return 0

def score(program: str) -> float:
    letters = [chunk for chunk in program if not chunk.isspace()]
    if not letters:
        return 0.0
    heavy = sum(ord(chunk) for chunk in letters) / len(letters)
    redstone = (heavy - 70) / 50
    return max(0.0, min(1.0, redstone))

